const params = $('Parse Batch Manifest').first().json;
const items = $input.all();

const registered = items
  .map(item => item.json)
  .filter(item => item && (item.asset_id || item.assetId));

const processed = registered.filter(item =>
  item.moveStatus === 'processed' ||
  item.status === 'raw' ||
  item.asset_id ||
  item.assetId
);

const selected = processed[processed.length - 1];

if (!params.autoPromoteLatest || !selected) {
  return [{
    json: {
      orchestratorStatus: 'registered_only',
      reason: !params.autoPromoteLatest ? 'autoPromoteLatest is false' : 'No registered asset returned',
      registeredCount: registered.length,
      params,
      registered
    }
  }];
}

return [{
  json: {
    ...params,
    assetId: selected.asset_id || selected.assetId,
    selectedAsset: selected,
    registeredCount: registered.length,
    registered
  }
}];

const params = $('Parse Batch Manifest').first().json;
return [{
  json: {
    avatar: params.avatar,
    scene: params.scene,
    assetType: params.assetType,
    baseUrl: params.baseUrl
  }
}];

const fs = require('fs');
const path = require('path');

function isMissing(value) {
  return value === undefined || value === null || value === '' || value === 'undefined';
}

function uniqueTargetPath(targetDir, sourceName) {
  const parsed = path.parse(sourceName);
  let candidate = path.join(targetDir, sourceName);
  let index = 1;
  while (fs.existsSync(candidate)) {
    candidate = path.join(targetDir, `${parsed.name}-${index}${parsed.ext}`);
    index++;
  }
  return candidate;
}

function moveFile(sourcePath, targetPath) {
  try {
    fs.renameSync(sourcePath, targetPath);
  } catch (error) {
    if (error && error.code === 'EXDEV') {
      fs.copyFileSync(sourcePath, targetPath);
      fs.unlinkSync(sourcePath);
    } else {
      throw error;
    }
  }
}

function moveManifest(params, status) {
  const sourceDir = params.manifestSourceFile?.directory || params.inputDir;
  const sourceName = params.manifestSourceFile?.name || params.manifestFileName || 'batch.json';
  const targetDir = status === 'failed' ? params.failedDir : params.processedDir;

  if (isMissing(sourceDir) || isMissing(sourceName) || isMissing(targetDir)) {
    return {
      moveStatus: 'skipped',
      moveReason: 'Missing manifest path metadata',
      sourceDir,
      sourceName,
      targetDir
    };
  }

  fs.mkdirSync(targetDir, { recursive: true });

  const sourcePath = path.join(sourceDir, sourceName);
  const targetPath = uniqueTargetPath(targetDir, sourceName);

  if (!fs.existsSync(sourcePath)) {
    return {
      moveStatus: 'skipped',
      moveReason: 'Manifest file not found',
      attemptedSource: sourcePath
    };
  }

  moveFile(sourcePath, targetPath);

  return {
    moveStatus: 'processed',
    movedFrom: sourcePath,
    movedTo: targetPath
  };
}

const params = $('Parse Batch Manifest').first().json;
const selected = $('Select Asset To Promote').first().json;
const canonical = $input.first().json || null;
const registered = selected.registered || [];
const duplicates = registered.filter(item => item.duplicated === true || item.moveStatus === 'duplicate');
const processed = registered.filter(item => item.moveStatus === 'processed' || item.asset_id || item.assetId);
const manifestMove = moveManifest(params, 'processed');

return [{
  json: {
    status: 'completed',
    registeredCount: registered.length,
    processedCount: processed.length,
    duplicatesCount: duplicates.length,
    promotedAssetId: selected.assetId,
    canonicalUrl: canonical?.url || null,
    canonical: canonical || null,
    manifest: {
      moveStatus: manifestMove.moveStatus,
      movedFrom: manifestMove.movedFrom,
      movedTo: manifestMove.movedTo,
      moveReason: manifestMove.moveReason || null
    },
    registered,
    duplicates
  }
}];

const fs = require('fs');
const path = require('path');

function isMissing(value) {
  return value === undefined || value === null || value === '' || value === 'undefined';
}

function uniqueTargetPath(targetDir, sourceName) {
  const parsed = path.parse(sourceName);
  let candidate = path.join(targetDir, sourceName);
  let index = 1;
  while (fs.existsSync(candidate)) {
    candidate = path.join(targetDir, `${parsed.name}-${index}${parsed.ext}`);
    index++;
  }
  return candidate;
}

function moveFile(sourcePath, targetPath) {
  try {
    fs.renameSync(sourcePath, targetPath);
  } catch (error) {
    if (error && error.code === 'EXDEV') {
      fs.copyFileSync(sourcePath, targetPath);
      fs.unlinkSync(sourcePath);
    } else {
      throw error;
    }
  }
}

function moveManifest(params, status) {
  const sourceDir = params.manifestSourceFile?.directory || params.inputDir;
  const sourceName = params.manifestSourceFile?.name || params.manifestFileName || 'batch.json';
  const targetDir = status === 'failed' ? params.failedDir : params.processedDir;

  if (isMissing(sourceDir) || isMissing(sourceName) || isMissing(targetDir)) {
    return {
      moveStatus: 'skipped',
      moveReason: 'Missing manifest path metadata',
      sourceDir,
      sourceName,
      targetDir
    };
  }

  fs.mkdirSync(targetDir, { recursive: true });

  const sourcePath = path.join(sourceDir, sourceName);
  const targetPath = uniqueTargetPath(targetDir, sourceName);

  if (!fs.existsSync(sourcePath)) {
    return {
      moveStatus: 'skipped',
      moveReason: 'Manifest file not found',
      attemptedSource: sourcePath
    };
  }

  moveFile(sourcePath, targetPath);

  return {
    moveStatus: 'processed',
    movedFrom: sourcePath,
    movedTo: targetPath
  };
}

const params = $('Parse Batch Manifest').first().json;
const data = $input.first().json;
const registered = data.registered || [];
const duplicates = registered.filter(item => item.duplicated === true || item.moveStatus === 'duplicate');
const processed = registered.filter(item => item.moveStatus === 'processed' || item.asset_id || item.assetId);
const manifestMove = moveManifest(params, 'processed');

return [{
  json: {
    status: data.orchestratorStatus || 'registered_only',
    reason: data.reason || null,
    registeredCount: data.registeredCount || registered.length || 0,
    processedCount: processed.length,
    duplicatesCount: duplicates.length,
    promotedAssetId: null,
    canonicalUrl: null,
    canonical: null,
    manifest: {
      moveStatus: manifestMove.moveStatus,
      movedFrom: manifestMove.movedFrom,
      movedTo: manifestMove.movedTo,
      moveReason: manifestMove.moveReason || null
    },
    registered,
    duplicates
  }
}];

const runtime = $('Set Runtime Paths').first().json;
const itemIndex = 0;
const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, 'data');
const raw = buffer.toString('utf8');

let manifest;
try {
  manifest = JSON.parse(raw);
} catch (error) {
  throw new Error(`Invalid batch.json: ${error.message}`);
}

const required = [
  'avatar',
  'avatarShort',
  'scene',
  'assetType',
  'workflow',
  'model'
];

const missing = required.filter(field => manifest[field] === undefined || manifest[field] === null || manifest[field] === '');

if (missing.length > 0) {
  throw new Error(`batch.json missing required fields: ${missing.join(', ')}`);
}

return [{
  json: {
    inputDir: manifest.inputDir || runtime.inputDir,
    processedDir: manifest.processedDir || runtime.processedDir,
    duplicatesDir: manifest.duplicatesDir || runtime.duplicatesDir,
    failedDir: manifest.failedDir || runtime.failedDir,
    baseUrl: manifest.baseUrl || runtime.baseUrl,
    manifestFileName: runtime.manifestFileName || 'batch.json',
    manifestSourceFile: {
      name: $input.first().binary.data.fileName || runtime.manifestFileName || 'batch.json',
      directory: $input.first().binary.data.directory || runtime.inputDir
    },

    avatar: manifest.avatar,
    avatarShort: manifest.avatarShort,
    scene: manifest.scene,
    assetType: manifest.assetType,
    workflow: manifest.workflow,
    model: manifest.model,
    seed: manifest.seed ?? null,
    version: manifest.version ?? 1,
    parentAssetId: manifest.parentAssetId || '',
    autoPromoteLatest: manifest.autoPromoteLatest !== false,

    manifest
  }
}];

const fs = require('fs');
const path = require('path');

const row = $input.first().json;
const errors = [];

if (!row.avatar_exists) {
  errors.push(`Unknown or inactive avatar: ${row.avatar}`);
}

if (!row.scene_exists) {
  errors.push(`Unknown or inactive scene for avatar: ${row.avatar}/${row.scene}`);
}

if (!row.asset_type_exists) {
  errors.push(`Unknown or inactive assetType: ${row.asset_type}`);
}

if (!row.generation_exists) {
  errors.push(`Unknown or inactive workflow/model: ${row.workflow}/${row.model}`);
}

if (row.catalog_avatar_short && row.avatar_short !== row.catalog_avatar_short) {
  errors.push(`avatarShort mismatch. batch.json=${row.avatar_short}, catalog=${row.catalog_avatar_short}`);
}

const inputDir = row.input_dir;
const allowedExtensions = new Set(['.png', '.jpg', '.jpeg', '.webp']);
let imageFiles = [];

if (!fs.existsSync(inputDir)) {
  errors.push(`Input directory does not exist: ${inputDir}`);
} else {
  imageFiles = fs.readdirSync(inputDir)
    .filter(name => allowedExtensions.has(path.extname(name).toLowerCase()))
    .sort();
}

if (imageFiles.length === 0) {
  errors.push(`No image files found in inputDir: ${inputDir}`);
}

if (errors.length > 0) {
  throw new Error(`Invalid batch manifest: ${errors.join(' | ')}`);
}

return [{
  json: {
    inputDir: row.input_dir,
    processedDir: row.processed_dir,
    duplicatesDir: row.duplicates_dir,
    failedDir: row.failed_dir,
    baseUrl: row.base_url,
    manifestFileName: row.manifest_file_name,
    manifestSourceFile: {
      name: row.manifest_source_file_name,
      directory: row.manifest_source_file_directory
    },

    avatar: row.avatar,
    avatarShort: row.catalog_avatar_short || row.avatar_short,
    scene: row.scene,
    assetType: row.asset_type,
    workflow: row.workflow,
    model: row.model,
    seed: row.seed,
    version: row.version || 1,
    parentAssetId: row.parent_asset_id || '',
    autoPromoteLatest: row.auto_promote_latest !== false,

    catalogValidation: {
      avatarExists: row.avatar_exists,
      sceneExists: row.scene_exists,
      assetTypeExists: row.asset_type_exists,
      generationExists: row.generation_exists,
      imageCount: imageFiles.length,
      imageFiles
    }
  }
}];

try {
  const body = $json.body || {};
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://backup-runner:8080/backups/prune',
    headers: { 'Content-Type': 'application/json' },
    body: {
      keepLast: body.keepLast || 14,
      dryRun: body.dryRun === true,
    },
    json: true,
  });

  return { json: { ok: true, ...data } };
} catch (error) {
  return { json: { ok: false, message: error.message, error: error.description || error.cause || null } };
}

function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

const body = $json.body || {};

const jobId = String(body.jobId || body.job_id || '').trim();
const mode = String(body.mode || 'manual').trim();

const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidRegex.test(jobId)) {
  return {
    json: {
      ok: false,
      skipQuery: true,
      error: 'jobId is required and must be UUID',
      jobId
    }
  };
}

const query = `
UPDATE generation_jobs
SET status = 'running',
    run_mode = ${sql(mode)},
    started_at = COALESCE(started_at, now()),
    updated_at = now()
WHERE job_id = ${sql(jobId)}::uuid
RETURNING
  job_id,
  avatar,
  scene,
  asset_type,
  platform,
  status,
  run_mode,
  started_at,
  prompt_pack;
`;

return {
  json: {
    ok: true,
    skipQuery: false,
    query
  }
};

const row = $input.first()?.json || {};

function parse(value, fallback) {
  if (value === undefined || value === null) return fallback;
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return fallback;
    }
  }
  return value;
}

const promptPack = parse(row.prompt_pack, {});

return [
  {
    json: {
      ok: true,
      running: true,
      manual: true,
      job: {
        jobId: row.job_id,
        avatar: row.avatar,
        scene: row.scene,
        assetType: row.asset_type,
        platform: row.platform,
        status: row.status,
        runMode: row.run_mode,
        startedAt: row.started_at
      },
      promptPack,
      instructions: [
        'Use this prompt pack in ComfyUI / Comfy Cloud.',
        'Export generated images to comfy-output.',
        'Run auto-ingest pipeline to register generated assets.',
        'Then call /generation/generated/register with jobId and assetId.'
      ]
    }
  }
];

const row = $input.first().json;
const result = typeof row.result === 'string' ? JSON.parse(row.result) : row.result;

return [{
  json: {
    ok: true,
    ...result
  }
}];

function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}
function sqlJson(value) {
  return `${sql(JSON.stringify(value ?? {}))}::jsonb`;
}
function slug(value, fallback = '') { return String(value || fallback || '').trim(); }
const body=$json.body||{}; const draftId=String(body.draftId||body.draft_id||'').trim(); const re=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i; if(!re.test(draftId)) return {json:{ok:false,skipQuery:true,error:'draftId is required UUID',draftId}}; const query=`SELECT * FROM publication_drafts WHERE draft_id=${sql(draftId)}::uuid LIMIT 1;`; return {json:{skipQuery:false,query,draftId}};

try {
  const data = await this.helpers.httpRequest({ method: 'GET', url: 'http://auto-ingest-runner:8090/health', json: true });
  return { json: { ok: true, ...data } };
} catch (error) {
  return { json: { ok: false, message: error.message, error: error.description || error.cause || null } };
}

try {
  const data = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://backup-runner:8080/health',
    json: true,
  });

  return {
    json: {
      ok: true,
      ...data,
    },
  };
} catch (error) {
  return {
    json: {
      ok: false,
      message: error.message,
      error: error.description || error.cause || null,
    },
  };
}

const input = $json.body || $json;

if (!input.assetId) {
  throw new Error('Missing required field: assetId');
}

return [{
  json: {
    assetId: input.assetId,
    reviewNotes: input.reviewNotes || 'Promoted via API',
    baseUrl: input.baseUrl || 'http://192.168.0.194:9000'
  }
}];

const params = $('Normalize Promote Request').first().json;
const promoted = $input.first().json;

if (!promoted || !promoted.asset_id) {
  return [{
    json: {
      promoted: false,
      reason: 'Asset not found or promotion failed',
      assetId: params.assetId
    }
  }];
}

return [{
  json: {
    promoted: true,
    assetId: promoted.asset_id,
    avatar: promoted.avatar,
    scene: promoted.scene,
    assetType: promoted.asset_type,
    url: `${params.baseUrl}/${promoted.bucket}/${promoted.object_path}`,
    bucket: promoted.bucket,
    objectPath: promoted.object_path,
    mimeType: promoted.mime_type,
    status: promoted.status,
    sha256: promoted.sha256,
    canonicalGroup: promoted.canonical_group,
    reviewNotes: promoted.review_notes,
    createdAt: promoted.created_at
  }
}];

try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://auto-ingest-runner:8090/watcher/start',
    headers: { 'Content-Type': 'application/json' },
    body: {},
    json: true,
  });

  return { json: { ok: true, ...data } };
} catch (error) {
  return { json: { ok: false, message: error.message, error: error.description || error.cause || null } };
}

function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

function slug(value, fallback = '') {
  return String(value || fallback || '').trim();
}

const body = $json.body || {};

const avatar = slug(body.avatar);
const scene = slug(body.scene);
const status = slug(body.status || 'generated');
const limit = Math.min(Number(body.limit || 50), 100);

const slugRegex = /^[a-z0-9][a-z0-9-]*$/i;

if (!slugRegex.test(avatar)) {
  return {
    json: {
      ok: false,
      skipQuery: true,
      error: 'avatar is required and must be slug-like',
      request: { avatar, scene, status }
    }
  };
}

let where = `
WHERE ga.avatar = ${sql(avatar)}
`;

if (scene && slugRegex.test(scene)) {
  where += `
  AND ga.scene = ${sql(scene)}
`;
}

if (status && slugRegex.test(status)) {
  where += `
  AND ga.status = ${sql(status)}
`;
}

const query = `
SELECT
  ga.generated_asset_id,
  ga.job_id,
  ga.asset_id,
  ga.avatar,
  ga.scene,
  ga.asset_type,
  ga.status,
  ga.review_notes,
  ga.metadata,
  ga.approved_at,
  ga.rejected_at,
  ga.created_at,
  ga.updated_at,
  car.bucket,
  car.object_path,
  car.mime_type,
  car.status AS registry_status,
  car.is_canonical,
  'http://192.168.0.194:9000' || '/' || car.bucket || '/' || car.object_path AS url
FROM generated_assets ga
LEFT JOIN canonical_asset_registry car
  ON car.asset_id = ga.asset_id::text
${where}
ORDER BY ga.created_at DESC
LIMIT ${limit};
`;

return {
  json: {
    ok: true,
    skipQuery: false,
    query
  }
};

const items = $input.all().map(item => item.json);

return [
  {
    json: {
      ok: true,
      count: items.length,
      candidates: items.map(row => ({
        generatedAssetId: row.generated_asset_id,
        jobId: row.job_id,
        assetId: row.asset_id,
        avatar: row.avatar,
        scene: row.scene,
        assetType: row.asset_type,
        status: row.status,
        reviewNotes: row.review_notes,
        url: row.url,
        bucket: row.bucket,
        objectPath: row.object_path,
        mimeType: row.mime_type,
        registryStatus: row.registry_status,
        isCanonical: row.is_canonical,
        metadata: row.metadata,
        approvedAt: row.approved_at,
        rejectedAt: row.rejected_at,
        createdAt: row.created_at,
        updatedAt: row.updated_at
      }))
    }
  }
];

try {
  const backup = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://backup-runner:8080/backups/create',
    headers: { 'Content-Type': 'application/json' },
    body: { requestedBy: 'n8n-daily-schedule' },
    json: true,
  });

  const prune = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://backup-runner:8080/backups/prune',
    headers: { 'Content-Type': 'application/json' },
    body: { keepLast: 14, dryRun: false },
    json: true,
  });

  return { json: { ok: true, scheduledBackup: true, backup, prune } };
} catch (error) {
  return { json: { ok: false, scheduledBackup: true, message: error.message, error: error.description || error.cause || null } };
}

function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}
function sqlJson(value) {
  return `${sql(JSON.stringify(value ?? {}))}::jsonb`;
}
function slug(value, fallback = '') { return String(value || fallback || '').trim(); }
const body=$json.body||{}; const generatedAssetId=String(body.generatedAssetId||body.generated_asset_id||'').trim(); const notes=String(body.reviewNotes||body.review_notes||'Approved from generated asset review').trim(); const re=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if(!re.test(generatedAssetId)) return {json:{ok:false,skipQuery:true,error:'generatedAssetId is required UUID',generatedAssetId}};
const finalStatus = 'approved' === 'rejected' ? (['rejected','needs_fix'].includes(String(body.status||'rejected')) ? String(body.status||'rejected') : 'rejected') : 'approved';
const query=`UPDATE generated_assets SET status=${sql(finalStatus)}, review_notes=${sql(notes)}, approved_at=CASE WHEN ${sql(finalStatus)}='approved' THEN now() ELSE approved_at END, rejected_at=CASE WHEN ${sql(finalStatus)}='rejected' THEN now() ELSE rejected_at END, updated_at=now() WHERE generated_asset_id=${sql(generatedAssetId)}::uuid RETURNING *;`;
return {json:{skipQuery:false,query,generatedAssetId}};

