node <<'NODE'
const fs = require('fs');
const path = require('path');

const PROJECT_PREFIX = 'silverman-blog-linkedin';
const BASE_PATH = process.env.SILVERMAN_BLOG_LINKEDIN_BASE_PATH || '/home/silverman/compartido_mac/silverman-blog-linkedin';
const BLOG_READY_PATH = path.join(BASE_PATH, 'blog-posts', 'ready');
const BLOG_PROCESSED_PATH = path.join(BASE_PATH, 'blog-posts', 'processed');
const BLOG_ERROR_PATH = path.join(BASE_PATH, 'blog-posts', 'error');
const LINKEDIN_REVIEW_PATH = path.join(BASE_PATH, 'linkedin-posts', 'review');
const RUNS_METADATA_PATH = path.join(BASE_PATH, 'metadata', 'runs');
const CAMPAIGNS_METADATA_PATH = path.join(BASE_PATH, 'metadata', 'campaigns');

const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
const OPENAI_BASE_URL = (process.env.OPENAI_BASE_URL || 'https://api.openai.com/v1').replace(/\/$/, '');
const OPENAI_MODEL = process.env.OPENAI_MODEL || 'gpt-4o-mini';

function ensureDir(dir) {
  fs.mkdirSync(dir, { recursive: true });
}

function nowIso() {
  return new Date().toISOString();
}

function safeWriteFile(filePath, content) {
  ensureDir(path.dirname(filePath));
  fs.writeFileSync(filePath, content, 'utf8');
}

function moveFileSafe(source, targetDir) {
  ensureDir(targetDir);
  const parsed = path.parse(source);
  let target = path.join(targetDir, parsed.base);
  if (fs.existsSync(target)) {
    const stamp = new Date().toISOString().replace(/[:.]/g, '-');
    target = path.join(targetDir, `${parsed.name}-${stamp}${parsed.ext}`);
  }
  fs.renameSync(source, target);
  return target;
}

function parseFrontmatter(markdown) {
  const match = markdown.match(/^---\s*\n([\s\S]*?)\n---\s*\n?/);
  const frontmatterRaw = match ? match[1] : '';
  const body = match ? markdown.slice(match[0].length) : markdown;
  const meta = {};
  for (const line of frontmatterRaw.split(/\r?\n/)) {
    const m = line.match(/^([A-Za-z0-9_-]+):\s*(.*)$/);
    if (!m) continue;
    let value = m[2].trim();
    value = value.replace(/^['"]|['"]$/g, '');
    meta[m[1]] = value;
  }
  return { meta, body, frontmatterRaw };
}

function makeOutputMarkdown({ post, variant, sourceBlogFile, sourceTitle, generatedAt }) {
  return `---\ntype: "linkedin-post"\nlanguage: "en"\nstatus: "review"\nsource_blog_file: "${sourceBlogFile}"\nsource_blog_title: "${sourceTitle.replace(/"/g, '\\"')}"\nvariant: "${variant}"\ngenerated_by: "n8n"\ngenerated_at: "${generatedAt}"\n---\n\n${post.trim()}\n`;
}

function extractSection(text, start, end) {
  const pattern = end
    ? new RegExp(`${start}\\s*([\\s\\S]*?)\\s*${end}`)
    : new RegExp(`${start}\\s*([\\s\\S]*)`);
  const match = text.match(pattern);
  return match ? match[1].trim() : '';
}

function parseAiOutput(text) {
  const executive = extractSection(text, '---EXECUTIVE---', '---TECHNICAL---');
  const technical = extractSection(text, '---TECHNICAL---', '---SHORT---');
  const short = extractSection(text, '---SHORT---', null);
  if (!executive || !technical || !short) {
    throw new Error('AI output did not match expected separators: ---EXECUTIVE---, ---TECHNICAL---, ---SHORT---');
  }
  return { executive, technical, short };
}

function buildPrompt({ title, fileName, markdown }) {
  return `You are helping Silverio Bernal, a practical Solutions Architect, convert a long-form blog article into LinkedIn posts.

Silverio's positioning:
- Practical Solutions Architect
- Focused on software architecture, AI-assisted SDLC, digital transformation, governance, efficiency, delivery discipline, and business value
- Target audience: recruiters, C-level leaders, CTOs, engineering managers, architects, and senior technical leaders
- Short-term goal: attract senior remote opportunities and roles around USD 7k/month
- Medium/long-term goal: build authority in AI, software architecture, digital transformation, and agility

Hard rules:
- Write in English.
- Do not write news commentary.
- Do not compare tools unless the article explicitly does.
- Do not write generic AI hype.
- Do not sound motivational without substance.
- Do not invent personal stories that are not present in the article.
- Do not mention Dairector.
- Do not mention that this was generated from a blog post.
- Do not use excessive emojis.
- Do not use exaggerated claims.

From the following blog article, generate exactly 3 LinkedIn post drafts:

1. Executive / recruiter version
   - Focus on business value, cost, risk, delivery, decision-making, and leadership
   - Should be understandable by CTOs, C-level leaders, VPs, and recruiters

2. Technical leadership version
   - Focus on architecture, boundaries, sequencing, trade-offs, governance, and engineering discipline
   - Should resonate with architects, tech leads, and engineering managers

3. Short provocative version
   - Shorter, sharper, more memorable
   - Strong hook
   - Still professional and grounded

Each LinkedIn post must:
- Start with a strong hook
- Use short paragraphs
- Provide value even if the reader does not open the blog
- Position Silverio as a senior practical Solutions Architect
- End with a soft CTA to read the full article, using placeholder {{BLOG_URL}}
- Include 4 to 6 relevant hashtags

Return the output in this exact format and nothing else:

---EXECUTIVE---
<post>

---TECHNICAL---
<post>

---SHORT---
<post>

Source file: ${fileName}
Article title: ${title}

Blog article:
${markdown}`;
}

async function callModel(prompt) {
  if (!OPENAI_API_KEY) {
    throw new Error('OPENAI_API_KEY environment variable is not set in the n8n container.');
  }

  const response = await fetch(`${OPENAI_BASE_URL}/chat/completions`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${OPENAI_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: OPENAI_MODEL,
      temperature: 0.72,
      messages: [
        {
          role: 'system',
          content: 'You are a senior editorial assistant for a practical Solutions Architect. You write direct, grounded, executive-friendly LinkedIn content in English.'
        },
        {
          role: 'user',
          content: prompt
        }
      ]
    })
  });

  const raw = await response.text();
  if (!response.ok) {
    throw new Error(`OpenAI-compatible API error ${response.status}: ${raw}`);
  }

  const data = JSON.parse(raw);
  const content = data?.choices?.[0]?.message?.content;
  if (!content) {
    throw new Error(`Model response did not include choices[0].message.content: ${raw}`);
  }
  return content;
}

async function main() {
  const runStartedAt = nowIso();
  ensureDir(BLOG_READY_PATH);
  ensureDir(BLOG_PROCESSED_PATH);
  ensureDir(BLOG_ERROR_PATH);
  ensureDir(LINKEDIN_REVIEW_PATH);
  ensureDir(RUNS_METADATA_PATH);
  ensureDir(CAMPAIGNS_METADATA_PATH);

  const allFiles = fs.readdirSync(BLOG_READY_PATH)
    .filter(file => file.toLowerCase().endsWith('.md'))
    .filter(file => !file.toLowerCase().includes('dairector'))
    .sort();

  const result = {
    project: PROJECT_PREFIX,
    workflow: 'silverman-blog-linkedin-01-generate-linkedin-from-blog',
    run_started_at: runStartedAt,
    base_path: BASE_PATH,
    model: OPENAI_MODEL,
    total_ready_files: allFiles.length,
    processed: [],
    failed: []
  };

  for (const fileName of allFiles) {
    const sourcePath = path.join(BLOG_READY_PATH, fileName);
    const slugBase = path.basename(fileName, '.md');
    const generatedAt = nowIso();

    try {
      const markdown = fs.readFileSync(sourcePath, 'utf8');
      const parsed = parseFrontmatter(markdown);
      const title = parsed.meta.title || markdown.match(/^#\s+(.+)$/m)?.[1]?.trim() || slugBase;
      const prompt = buildPrompt({ title, fileName, markdown });
      const aiOutput = await callModel(prompt);
      const posts = parseAiOutput(aiOutput);

      const outputFiles = {
        executive: path.join(LINKEDIN_REVIEW_PATH, `${slugBase}-executive.md`),
        technical: path.join(LINKEDIN_REVIEW_PATH, `${slugBase}-technical.md`),
        short: path.join(LINKEDIN_REVIEW_PATH, `${slugBase}-short.md`)
      };

      safeWriteFile(outputFiles.executive, makeOutputMarkdown({ post: posts.executive, variant: 'executive', sourceBlogFile: fileName, sourceTitle: title, generatedAt }));
      safeWriteFile(outputFiles.technical, makeOutputMarkdown({ post: posts.technical, variant: 'technical', sourceBlogFile: fileName, sourceTitle: title, generatedAt }));
      safeWriteFile(outputFiles.short, makeOutputMarkdown({ post: posts.short, variant: 'short', sourceBlogFile: fileName, sourceTitle: title, generatedAt }));

      const campaignMetadata = {
        project: PROJECT_PREFIX,
        source_blog_file: fileName,
        source_blog_title: title,
        slug: slugBase,
        status: 'linkedin_review_generated',
        generated_at: generatedAt,
        linkedin_review_files: outputFiles,
        excluded_terms: ['Dairector'],
        model: OPENAI_MODEL
      };
      const campaignPath = path.join(CAMPAIGNS_METADATA_PATH, `${slugBase}.json`);
      safeWriteFile(campaignPath, JSON.stringify(campaignMetadata, null, 2));

      const processedPath = moveFileSafe(sourcePath, BLOG_PROCESSED_PATH);

      result.processed.push({
        source_blog_file: fileName,
        title,
        processed_path: processedPath,
        linkedin_review_files: outputFiles,
        campaign_metadata_file: campaignPath
      });
    } catch (error) {
      const errorPath = path.join(BLOG_ERROR_PATH, `${slugBase}.error.json`);
      safeWriteFile(errorPath, JSON.stringify({
        project: PROJECT_PREFIX,
        source_blog_file: fileName,
        error: error.message,
        failed_at: nowIso()
      }, null, 2));
      result.failed.push({ source_blog_file: fileName, error: error.message, error_metadata_file: errorPath });
    }
  }

  result.run_finished_at = nowIso();
  const runStamp = result.run_finished_at.replace(/[:.]/g, '-');
  const runPath = path.join(RUNS_METADATA_PATH, `${PROJECT_PREFIX}-run-${runStamp}.json`);
  result.run_metadata_file = runPath;
  safeWriteFile(runPath, JSON.stringify(result, null, 2));

  console.log(JSON.stringify(result, null, 2));
}

main().catch(error => {
  console.error(JSON.stringify({
    project: PROJECT_PREFIX,
    workflow: 'silverman-blog-linkedin-01-generate-linkedin-from-blog',
    fatal_error: error.message,
    failed_at: nowIso()
  }, null, 2));
  process.exit(1);
});
