SELECT
  EXISTS (
    SELECT 1
    FROM canonical_asset_registry
    WHERE sha256 = '{{ $json.sha256 }}'
  ) AS duplicated_in_db;

parameters.jsCode:
const seen = new Set();

return $input.all().map(item => {
  const data = item.json;

  const duplicatedInDb = data.duplicated_in_db === true;
  const duplicatedInBatch = seen.has(data.sha256);

  if (!duplicatedInBatch) {
    seen.add(data.sha256);
  }

  const duplicated = duplicatedInDb || duplicatedInBatch;

  return {
    json: {
      ...data,
      duplicated,
      duplicateReason: duplicatedInDb
        ? 'database'
        : duplicatedInBatch
          ? 'batch'
          : null
    },
    binary: item.binary
  };
});

const fs = require('fs');
const path = require('path');

const isMissing = value =>
  !value || value === 'undefined' || value === undefined || value === null;

function uniqueTargetPath(targetDir, sourceName) {
  const parsed = path.parse(sourceName);
  let candidate = path.join(targetDir, sourceName);
  let index = 1;

  while (fs.existsSync(candidate)) {
    candidate = path.join(targetDir, `${parsed.name}-${index}${parsed.ext}`);
    index++;
  }

  return candidate;
}

function moveFile(sourcePath, targetPath) {
  try {
    fs.renameSync(sourcePath, targetPath);
  } catch (error) {
    if (error && error.code === 'EXDEV') {
      fs.copyFileSync(sourcePath, targetPath);
      fs.unlinkSync(sourcePath);
    } else {
      throw error;
    }
