const body=$json.body||{}; const avatar=slug(body.avatar); const scene=slug(body.scene); const platform=slug(body.platform,'instagram'); const re=/^[a-z0-9][a-z0-9-]*$/i;
if(!re.test(avatar)||!re.test(scene)||!re.test(platform)) return {json:{ok:false,skipQuery:true,error:'avatar, scene and platform are required slug-like values',request:{avatar,scene,platform}}};
const query=`SELECT ac.avatar, ac.display_name AS avatar_display_name, ac.avatar_short, sc.scene, sc.display_name AS scene_display_name, ${sql(platform)} AS platform, COALESCE(sb.visual_intent, sc.description, sc.display_name, sc.scene) AS visual_intent, COALESCE(sb.allowed_mood,'natural, warm, cinematic') AS allowed_mood, COALESCE(sb.content_angle,'') AS content_angle, COALESCE(sb.prompt_notes,'') AS prompt_notes FROM avatar_catalog ac JOIN scene_catalog sc ON sc.avatar=ac.avatar LEFT JOIN scene_brief_catalog sb ON sb.avatar=ac.avatar AND sb.scene=sc.scene WHERE ac.avatar=${sql(avatar)} AND sc.scene=${sql(scene)} AND COALESCE(ac.is_enabled,true)=true AND COALESCE(sc.is_enabled,true)=true LIMIT 1;`;
return {json:{ok:true,skipQuery:false,query}};

const row=$input.first()?.json||{}; if(!row.avatar) return [{json:{ok:false,error:'Post brief context not found'}}];
const sceneName=row.scene_display_name||row.scene; const visualDirection=row.visual_intent||`${row.avatar_display_name} in ${sceneName}`;
const captionIdea=`Una pausa en ${sceneName.toLowerCase()}: movimiento natural, presencia y una historia que apenas empieza.`;
return [{json:{ok:true,avatar:row.avatar,scene:row.scene,platform:row.platform,captionIdea,visualDirection,promptIntent:`${visualDirection}. ${row.prompt_notes||''}`.trim(),emotion:row.allowed_mood,cta:row.platform==='instagram'?'¿Con cuál versión te quedas?':'Share your first impression.',contentAngle:row.content_angle||null}}];

